public class ImageCropTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String size(java.awt.image.BufferedImage img) {
        if (img == null) {
            return "(null image)";
        }
        return img.getWidth() + "x" + img.getHeight();
    }

    static String colorAt(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "(null image)";
        }
        if (x >= img.getWidth() || y >= img.getHeight()) {
            return "(out of range)";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage makeSource() {
        java.awt.image.BufferedImage src =
                new java.awt.image.BufferedImage(4, 3, java.awt.image.BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < 3; y++) {
            for (int x = 0; x < 4; x++) {
                src.setRGB(x, y, ((x + 1) << 16) | ((y + 1) << 8) | 0x40);
            }
        }
        return src;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage src = makeSource();
            java.awt.image.BufferedImage inner = ImageCrop.crop(src, 1, 1, 2, 2);
            check("crop(1,1,2,2) size", "2x2", size(inner));
            check("crop(1,1,2,2) top-left is src(1,1)", "#020240", colorAt(inner, 0, 0));
            check("crop(1,1,2,2) bottom-right is src(2,2)", "#030340", colorAt(inner, 1, 1));
            check("crop returns a new image", true, inner != null && inner != src);

            java.awt.image.BufferedImage wide = ImageCrop.crop(src, 2, 1, 10, 10);
            check("crop(2,1,10,10) clamps size", "2x2", size(wide));
            check("crop(2,1,10,10) top-left is src(2,1)", "#030240", colorAt(wide, 0, 0));

            java.awt.image.BufferedImage negative = ImageCrop.crop(src, -5, -5, 2, 2);
            check("crop(-5,-5,2,2) size", "2x2", size(negative));
            check("crop(-5,-5,2,2) top-left is src(0,0)", "#010140", colorAt(negative, 0, 0));

            java.awt.image.BufferedImage past = ImageCrop.crop(src, 9, 9, 2, 2);
            check("crop(9,9,2,2) shrinks to one pixel", "1x1", size(past));
            check("crop(9,9,2,2) holds src(3,2)", "#040340", colorAt(past, 0, 0));

            check("src unchanged", "#010140", colorAt(src, 0, 0));
            check("src size unchanged", "4x3", size(src));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

