import java.awt.image.BufferedImage;

public class ImageCrop {

    public static BufferedImage crop(BufferedImage src, int x, int y, int w, int h) {
        int startX = Math.max(0, Math.min(x, src.getWidth() - 1));
        int startY = Math.max(0, Math.min(y, src.getHeight() - 1));
        int width = Math.max(1, Math.min(w, src.getWidth() - startX));
        int height = Math.max(1, Math.min(h, src.getHeight() - startY));
        BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
        for (int row = 0; row < height; row++) {
            for (int col = 0; col < width; col++) {
                out.setRGB(col, row, src.getRGB(startX + col, startY + row));
            }
        }
        return out;
    }
}
